import pytest

from bedrock_protocol import v975, v1001, v2168

EMPTY_ITEM_BLOB = "\x00" * 10

# generated by gophertunnel 6353c49:
# packet.InventorySlot{WindowID: 12, Slot: 3}
V1001_ABSENT = bytes.fromhex("0c0300000000000000000000")

# generated by gophertunnel 6353c49:
# packet.InventorySlot{WindowID: 12, Slot: 3,
#   Container: protocol.Option(protocol.FullContainerName{ContainerID: 59,
#     DynamicContainerID: protocol.Option[uint32](3)}),
#   StorageItem: protocol.Option(protocol.ItemInstance{}),
#   NewItem: protocol.ItemInstance{StackNetworkID: 9,
#     Stack: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 5, MetadataValue: 3}, Count: 1}}}
V1001_PRESENT = bytes.fromhex("0c03013b01030000000100000000000000000500010003010012000a00000000000000000000")

# generated by gophertunnel b8bd735:
# packet.InventorySlot{WindowID: 12, Slot: 3}
V2168_ABSENT = bytes.fromhex("0c0300000000000000000000")

# generated by gophertunnel b8bd735:
# packet.InventorySlot{WindowID: 12, Slot: 3,
#   Container: protocol.Option(protocol.FullContainerName{ContainerID: 59,
#     DynamicContainerID: protocol.Option[uint32](3)}),
#   StorageItem: protocol.Option(protocol.ItemInstance{}),
#   NewItem: protocol.ItemInstance{StackNetworkID: 9,
#     Stack: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 5, MetadataValue: 3}, Count: 1}}}
V2168_PRESENT = bytes.fromhex("0c03013b010300000001000000000000000005000100030112000a00000000000000000000")

GOLDENS = [
    pytest.param(v975.InventorySlotPacket(inventory_id=12, slot=3), V1001_ABSENT, id="v975-absent"),
    pytest.param(v1001.InventorySlotPacket(inventory_id=12, slot=3), V1001_ABSENT, id="v1001-absent"),
    pytest.param(
        v1001.InventorySlotPacket(
            inventory_id=12,
            slot=3,
            full_container_name=v1001.FullContainerName(name=v1001.ContainerEnumName.CURSOR_CONTAINER, dynamic_id=3),
            storage_item=v1001.SerializedNetworkItemStackDescriptor(),
            item=v1001.SerializedNetworkItemStackDescriptor(
                id=5,
                stack_size=1,
                aux_value=3,
                net_id_variant=v1001.ItemStackNetId(raw_id=9),
                user_data_buffer=EMPTY_ITEM_BLOB,
            ),
        ),
        V1001_PRESENT,
        id="v1001-present",
    ),
    pytest.param(v2168.InventorySlotPacket(inventory_id=12, slot=3), V2168_ABSENT, id="v2168-absent"),
    pytest.param(
        v2168.InventorySlotPacket(
            inventory_id=12,
            slot=3,
            full_container_name=v2168.FullContainerName(name=v2168.ContainerEnumName.CURSOR_CONTAINER, dynamic_id=3),
            storage_item=v2168.SerializedNetworkItemStackDescriptor(),
            item=v2168.SerializedNetworkItemStackDescriptor(
                id=5,
                stack_size=1,
                aux_value=3,
                net_id_variant=9,
                user_data_buffer=EMPTY_ITEM_BLOB,
            ),
        ),
        V2168_PRESENT,
        id="v2168-present",
    ),
]


@pytest.mark.parametrize("version", [v975, v1001, v2168])
def test_inventory_slot_is_packet_50(version):
    assert version.PACKETS[50] is version.InventorySlotPacket


def test_inventory_slot_is_one_shape_across_975_and_1001():
    assert v975.InventorySlotPacket is v1001.InventorySlotPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_inventory_slot_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_inventory_slot_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_inventory_slot_is_the_same_bytes_at_1001_and_2168_when_nothing_is_present():
    assert V2168_ABSENT == V1001_ABSENT


def test_inventory_slot_net_id_is_one_byte_shorter_at_2168():
    assert len(V2168_PRESENT) + 1 == len(V1001_PRESENT)


def test_inventory_slot_1001_body_leaves_trailing_bytes_at_2168():
    with pytest.raises(ValueError, match="trailing bytes"):
        v2168.InventorySlotPacket.from_bytes(V1001_PRESENT)


def test_inventory_slot_2168_body_is_rejected_at_1001():
    with pytest.raises(ValueError, match="at byte"):
        v1001.InventorySlotPacket.from_bytes(V2168_PRESENT)
